CREATE TABLE IF NOT EXISTS billing_accounts (organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,plan_code text NOT NULL DEFAULT 'essential' CHECK(plan_code IN ('essential','professional','business')),status text NOT NULL DEFAULT 'trial' CHECK(status IN ('trial','active','pending','restricted')),paypal_subscription_id text,offer_id text,current_period_start timestamptz,current_period_end timestamptz,cancel_at_period_end boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_billing_account_paypal_subscription ON billing_accounts(paypal_subscription_id) WHERE paypal_subscription_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS billing_events (event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,paypal_event_id text,paypal_subscription_id text,event_type text NOT NULL,status text,offer_id text,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(paypal_event_id));
CREATE INDEX IF NOT EXISTS idx_billing_events_org_created ON billing_events(organization_id,created_at DESC);
ALTER TABLE billing_accounts ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_accounts FORCE ROW LEVEL SECURITY;
ALTER TABLE billing_events ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_events FORCE ROW LEVEL SECURITY;
CREATE POLICY billing_accounts_org_isolation ON billing_accounts USING(organization_id::text=current_setting('app.organization_id',true)) WITH CHECK(organization_id::text=current_setting('app.organization_id',true));
CREATE POLICY billing_events_org_isolation ON billing_events USING(organization_id::text=current_setting('app.organization_id',true)) WITH CHECK(organization_id::text=current_setting('app.organization_id',true));
